#!/usr/bin/env python3
"""Generate interop reference files for the Delta/x86 BCJ support.

The .xz files in this directory are generated by the lzma module of
CPython 3.12, which statically links the reference implementation
liblzma (https://tukaani.org/xz/). They are used by the Go tests to
verify interoperability. Regenerate with:

    python gen_ref.py

The same payload file payload.bin is written by all variants.
"""
import lzma
import os

HERE = os.path.dirname(os.path.abspath(__file__))


def payload():
    data = bytearray()
    # Text prefix so a Delta distance of 1 sees structured data.
    data += b"The quick brown fox jumps over the lazy dog.\n" * 8
    # CALL/JMP instructions at a range of positions, including several
    # close enough that their displacement fields overlap. These
    # sequences exercise the x86 BCJ state machine directly.
    data += bytes.fromhex(
        "e800000000"
        "e8fcffffff"
        "e900000000"
        "e8e800000000"
        "e800e8000000"
        "e80000e80000"
        "e8000000e800"
        "0f8001020304"
        "aae800000000"
    )
    # A longer deterministic pseudo-random body so LZMA2 has real
    # matches to work with and so Delta with larger distances has
    # history to reference.
    state = 0x12345678
    for _ in range(4096):
        state = (state * 1103515245 + 12345) & 0xffffffff
        data.append((state >> 16) & 0xff)
        if len(data) % 97 == 0:
            data += b"\xe9\x00\x00\x00\x00"
    return bytes(data)


CHECKS = {
    "crc64": lzma.CHECK_CRC64,
    "crc32": lzma.CHECK_CRC32,
    "sha256": lzma.CHECK_SHA256,
    "none": lzma.CHECK_NONE,
}


def chain(name):
    if name == "lzma2":
        return [{"id": lzma.FILTER_LZMA2, "preset": 6}]
    lzma2 = {"id": lzma.FILTER_LZMA2, "preset": 6}
    if name == "x86":
        return [{"id": lzma.FILTER_X86}, lzma2]
    if name.startswith("delta"):
        dist = int(name.split("-")[1])
        d = {"id": lzma.FILTER_DELTA, "dist": dist}
        if name.endswith("-x86"):
            return [d, {"id": lzma.FILTER_X86}, lzma2]
        return [d, lzma2]
    raise ValueError(name)


def main():
    data = payload()
    with open(os.path.join(HERE, "payload.bin"), "wb") as f:
        f.write(data)

    variants = [
        ("lzma2", "crc64"),
        ("x86", "crc64"),
        ("delta-1", "crc64"),
        ("delta-7", "crc64"),
        ("delta-1-x86", "crc64"),
        ("x86", "crc32"),
        ("x86", "sha256"),
        ("x86", "none"),
        ("delta-7-x86", "none"),
    ]
    for filters_name, check_name in variants:
        out = lzma.compress(
            data,
            format=lzma.FORMAT_XZ,
            check=CHECKS[check_name],
            filters=chain(filters_name),
        )
        path = os.path.join(
            HERE, f"ref_{filters_name}_{check_name}.xz")
        with open(path, "wb") as f:
            f.write(out)
        print(os.path.basename(path), len(out))

    # A stream using the ARM BCJ filter (ID 0x07), which this library
    # does not support.
    unsupported = lzma.compress(
        data,
        format=lzma.FORMAT_XZ,
        check=lzma.CHECK_CRC64,
        filters=[
            {"id": lzma.FILTER_ARM},
            {"id": lzma.FILTER_LZMA2, "preset": 6},
        ],
    )
    with open(os.path.join(HERE, "ref_unsupported_arm_crc64.xz"),
              "wb") as f:
        f.write(unsupported)
    print("ref_unsupported_arm_crc64.xz", len(unsupported))


if __name__ == "__main__":
    main()
